function chunkAverage(arr, size) {
  const result = [];
  for (let i = 0; i < arr.length; i += size) {
    const chunk = arr.slice(i, i + size);
    result.push(chunk.reduce((a, b) => a + b, 0) / chunk.length);
  }
  return result;
}
